func (e *Engine) Order(id int64) (Order, bool) {
	e.mu.Lock()
	defer e.mu.Unlock()
	o := e.orders[id]
	if o == nil {
		return Order{}, false
	}
	return *o, true
}

// Orders 返回全部已接受订单的快照，按订单编号排列。
func (e *Engine) Orders() []Order {
	e.mu.Lock()
	defer e.mu.Unlock()
	out := make([]Order, 0, len(e.orders))
	for id := int64(1); id <= e.nextOrderID; id++ {
		if o := e.orders[id]; o != nil {
			out = append(out, *o)
		}
	}
	return out
}

// Records 返回全部事件记录的副本，按发生先后排列。
func (e *Engine) Records() []Record {
	e.mu.Lock()
	defer e.mu.Unlock()
	out := make([]Record, len(e.records))
	copy(out, e.records)
	for i := range out {
		if out[i].RiskQuoteRefs != nil {
			refs := make([]RiskQuoteRef, len(out[i].RiskQuoteRefs))
			copy(refs, out[i].RiskQuoteRefs)
			out[i].RiskQuoteRefs = refs
		}
		if out[i].AmtQuoteRefs != nil {
			refs := make([]RiskQuoteRef, len(out[i].AmtQuoteRefs))
			copy(refs, out[i].AmtQuoteRefs)
			out[i].AmtQuoteRefs = refs
		}
	}
	return out
}

// SetMaxPosition 设置合约的非负最大持仓量。每个合约下单前必须先设置。
// 下调（或首次设置导致超限）时，立即从最后接受的买单开始取消其全部剩余量，
// 直到满足新限额；若持仓本身已超限，则撤掉全部未成交买单，卖单不受影响。
// 返回本次被撤销的订单编号列表（按撤销顺序）。
func (e *Engine) SetMaxPosition(symbol string, max int64) ([]int64, error) {
	if symbol == "" {
		return nil, fmt.Errorf("合约代码不能为空")
	}
	if max < 0 {
		return nil, fmt.Errorf("最大持仓量不能为负: %d", max)
	}
	e.mu.Lock()
	defer e.mu.Unlock()

	st := e.state(symbol)
	st.maxSet = true
	st.maxPosition = max

	// “持仓本身已超限”与“持仓加有效买单剩余才超限”共用同一套有效买单判断
	// （activeBuy，经 lastActivePositionBuyLocked 选择）、原先的接受次序与同一个
	// 撤单循环：
	// 每张订单都在选择当时重新判断是否仍可撤销，每次撤销其全部剩余量。
	//   - 持仓本身已超过新限额：持续撤到该合约没有有效买单为止，持仓继续保留、
	//     不自动平仓（st.position 不随撤单变化，故 holdingOver 只判定一次）；
	//   - 普通超限：在 持仓 + 有效买单剩余量 <= 新限额 后即停止，恰好等于时
	//     保留较早接受的订单。
	holdingOver := st.position > max

	var canceled []int64
	for holdingOver || st.position+st.reservedBuy > max {
		target := e.lastActivePositionBuyLocked(st)
		if target == nil {
			break // 无有效买单可撤（reservedBuy 已为 0）时兜底结束
		}
		if holdingOver {
			e.cancelLocked(target, fmt.Sprintf("持仓 %d 已超过新限额 %d，撤销剩余买单", st.position, max))
		} else {
			e.cancelLocked(target, fmt.Sprintf("持仓限额下调至 %d，撤销最后接受的剩余买单", max))
		}
		canceled = append(canceled, target.ID)
	}
	return canceled, nil
}

// lastActivePositionBuyLocked 是合约持仓限额下调撤单时的买单选择规则：在该合约的
// 买单接受序列 st.buyOrderIDs（最早接受在前）上自后向前，返回最后接受的一张有效
// 买单（有效判断见 activeBuy，与全账户各功能共用同一规则，不存在、已全部成交或
// 已撤销的订单一律跳过）。其他合约的买单与该合约的卖单不在本合约的接受序列中，
// 永远不会被选中；成功修改过总量或限价的订单仍按最初接受的位置参与，修改不视为
// 重新下单。调用方每撤一张后都应重新调用，以按撤销当时的状态判断后续订单是否仍
// 可撤销。调用时须持有引擎锁。
func (e *Engine) lastActivePositionBuyLocked(st *symbolState) *Order {
	for i := len(st.buyOrderIDs) - 1; i >= 0; i-- {
		if o := e.orders[st.buyOrderIDs[i]]; activeBuy(o) {
			return o
		}
	}
	return nil
}

// UpdateQuote 提交合约报价。只有连续序号才能推进最新报价：
// 跨号报价进入等待，缺口补齐后按序号依次生效，返回本次新生效的报价条数；
// 重复序号且内容（时刻、价格）一致时不产生新事件（返回 0）；
// 重复序号但内容不同时报错并保留原值（返回 0 和错误）。
func (e *Engine) UpdateQuote(symbol string, q Quote) (int, error) {
	if symbol == "" {
		return 0, fmt.Errorf("合约代码不能为空")
	}
	if q.Seq <= 0 {
		return 0, fmt.Errorf("报价序号必须从 1 开始: %d", q.Seq)
	}
	if q.Price <= 0 {
		return 0, fmt.Errorf("报价价格必须为正: %d", q.Price)
	}
	e.mu.Lock()
	defer e.mu.Unlock()

// 检查始终生效，不依赖任何保护或限额是否开启）；或买单申请后
// “已持仓数量 + 该合约有效买单剩余量 + 本次申请数量”合计超出 int64 范围
// （合约持仓限额检查始终生效，三个数各自合法并不代表合计可表示）。
// 返回该错误的开日、调限额、设置金额上限、报价、下单或成交调用整体不生效：
// 除拒绝记录外不改变任何业务状态。
var ErrInt64Overflow = errors.New("净值、亏损或持仓金额超出 int64 范围")

// Side 表示买卖方向。
type Side int

const (
	// Buy 是买入方向（只允许先买后卖）。
	Buy Side = iota + 1
	// Sell 是卖出方向。
	Sell
)

// String 返回方向的中文描述。
func (s Side) String() string {
	switch s {
	case Buy:
		return "买入"
	case Sell:
		return "卖出"
	default:
		return "未知方向"
	}
}

